def fail_invalid():
    sys.stdout.write('{"error":"invalid-input"}\n')
    sys.stdout.flush()
    raise SystemExit(2)


def main():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        fail_invalid()
    if len(raw) > MAX_INPUT_BYTES:
        fail_invalid()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        fail_invalid()
    try:
        doc = parse_document(text)
        output = build_output(doc)
    except InvalidInput:
        fail_invalid()
    except RecursionError:
        fail_invalid()
    except Exception:
        fail_invalid()
    sys.stdout.write(json.dumps(output, separators=(",", ":"), allow_nan=False))
    sys.stdout.write("\n")
    sys.stdout.flush()
    raise SystemExit(0)


if __name__ == "__main__":
    main()
